def is_in_set(n, a, b):
    visited = set([1])
    queue = [1]

    while queue:
        x = queue.pop(0)
        if x * a not in visited and x * a <= n:
            visited.add(x * a)
            queue.append(x * a)
        if x + b not in visited and x + b <= n:
            visited.add(x + b)
            queue.append(x + b)

    return n in visited

def main():
    t = int(input().strip())
    results = []
    for _ in range(t):
        n, a, b = map(int, input().strip().split())
        results.append("Yes" if is_in_set(n, a, b) else "No")
    print("\n".join(results))

main()
